CREATE TABLE public.project_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE, user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, path text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes > 0), kind text NOT NULL CHECK(kind IN ('image','video','audio','logo','reference','music','voice')), description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.project_assets TO authenticated; GRANT ALL ON public.project_assets TO service_role; ALTER TABLE public.project_assets ENABLE ROW LEVEL SECURITY; CREATE POLICY assets_owner ON public.project_assets FOR ALL TO authenticated USING (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid())) WITH CHECK (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid())); CREATE INDEX project_assets_project ON public.project_assets(project_id);